import{DEFAULTS,matches,shuffle,csvTracks,roundStart,uniqueTracks}from'./core.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();const demoSongs=[{title:'Neon Steps',artist:'GuessKar Studio',notes:[60,64,67,72,67,64,62,65]},{title:'Moonlight Arcade',artist:'GuessKar Studio',notes:[69,72,76,74,72,69,65,67]},{title:'Sunday Windows',artist:'GuessKar Studio',notes:[65,69,72,69,67,64,60,64]},{title:'Midnight Metro',artist:'GuessKar Studio',notes:[48,55,58,60,58,55,53,55]},{title:'Lime Soda',artist:'GuessKar Studio',notes:[72,76,79,76,74,77,81,79]}];
let lists,settings;try{lists=JSON.parse(localStorage.getItem('gk-lists'));settings={...DEFAULTS,...JSON.parse(localStorage.getItem('gk-settings'))};}catch{}settings||={...DEFAULTS};if(!Array.isArray(lists))lists=[{id:'demo',name:'The little demo mix',source:'demo',selected:true,tracks:demoSongs.map((s,i)=>({...s,id:'demo-'+i,source:'demo'}))}];
let page='play',session=null,audio=null,source=null,playing=false,buffer=null,db=null,player=null,ytReady=null,ytTimer=null,playTimer=null,playToken=0;
const main=$('#main');function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}function save(){try{localStorage.setItem('gk-lists',JSON.stringify(lists));localStorage.setItem('gk-settings',JSON.stringify(settings));}catch{toast('Storage is full. Export or remove a collection to free space.');}}
const dbReady=new Promise(resolve=>{const q=indexedDB.open('guesskar-audio',1);q.onupgradeneeded=()=>q.result.createObjectStore('files');q.onsuccess=()=>{db=q.result;resolve();};q.onerror=()=>resolve();});async function fileStore(method,key,value){await dbReady;if(!db)throw Error('Audio storage is unavailable. Enable browser storage and try again.');return new Promise((resolve,reject)=>{const tx=db.transaction('files',method==='get'?'readonly':'readwrite');const q=tx.objectStore('files')[method](...(method==='put'?[value,key]:[key]));let result;q.onsuccess=()=>result=q.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);});}
function context(){audio||=new AudioContext({latencyHint:'interactive'});return audio;}function stop(){playToken++;clearTimeout(playTimer);clearInterval(ytTimer);try{source?.stop();}catch{}source=null;player?.pauseVideo?.();playing=false;}
function demoBuffer(t){const ctx=context(),b=ctx.createBuffer(1,ctx.sampleRate*14,ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++){const time=i/ctx.sampleRate,n=Math.floor(time/.32)%t.notes.length,f=440*2**((t.notes[n]-69)/12),env=Math.min(1,(time%.32)/.004)*Math.exp(-(time%.32)*9);d[i]=(.23*Math.sin(2*Math.PI*f*time)+.07*Math.sin(4*Math.PI*f*time))*env;}return b;}
function levels(active=-1){return `<div class="levels">${settings.lengths.map((v,i)=>`<div class="level ${i===active?'active':''}"><b>${v} s</b><small>${settings.points[i].toLocaleString()} pts</small></div>`).join('')}</div>`;}
function navigate(p){if(session&&!session.done){modal(`<h2>Leave this game?</h2><p>Your current session will end. Your collections and settings are saved.</p><button class="primary" id="leave">Leave game</button>`);$('#leave').onclick=()=>{stop();session=null;$('#modal').close();navigate(p);};return;}stop();session=null;page=p;render();}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(session)return renderGame();if(page==='library')return renderLibrary();if(page==='how')return renderHelp();renderSetup();}
function playable(t){return ['local','demo','youtube'].includes(t.source);}
function pool(){return uniqueTracks(lists.filter(l=>l.selected).flatMap(l=>l.tracks).filter(playable));}
function renderSetup(){const count=pool().length;main.innerHTML=`<section class="hero"><div><div class="eyebrow"><i></i> LESS AUDIO. MORE INSTINCT.</div><h1>Know it in a<br><em>heartbeat.</em></h1><p class="lead">A split second of sound. A song you know by heart.<br>How little do you need to name that tune?</p></div><div class="hero-art" aria-hidden="true"><span class="spark">✧</span><div class="record"><div class="record-label">♫</div></div><span class="float-pill">♫ &nbsp; 0.1 seconds. You got this.</span><span class="float-pill bottom">✦ &nbsp; Your playlists. Your game.</span></div></section><div class="steps"><div class="step"><span class="step-number">01</span><div><strong>Bring your music</strong><small>Pick a playlist. Set the vibe.</small></div></div><div class="step"><span class="step-number">02</span><div><strong>Listen a little</strong><small>Start with just 0.1 seconds.</small></div></div><div class="step"><span class="step-number">03</span><div><strong>Trust your ears</strong><small>Guess sooner. Score bigger.</small></div></div></div><div class="setup-grid"><section class="panel"><div class="panel-heading"><h2><span>♫</span> Your soundtrack</h2><button class="text-button" id="add"><span>＋</span> Add music</button></div><p class="panel-desc">Choose one or mix a few. We'll shuffle the rest.</p><div class="collections">${lists.map((l,i)=>`<label class="collection ${l.selected?'':'off'}"><span class="cover ${['','blue','purple'][i%3]}">${l.source==='youtube'?'▷':l.source==='metadata'?'≋':'♫'}</span><span class="collection-info"><strong>${esc(l.name)}</strong><small>${l.tracks.filter(playable).length} playable tracks <span class="source-tag">${l.source==='demo'?'DEMO':l.source==='youtube'?'YOUTUBE':l.source==='metadata'?'CSV':'LOCAL AUDIO'}</span></small></span><input type="checkbox" class="check" data-list="${l.id}" ${l.selected?'checked':''} aria-label="Select ${esc(l.name)}"></label>`).join('')}</div><div class="collection-footer"><span><i></i> ${lists.filter(l=>l.selected).length} collection${lists.filter(l=>l.selected).length===1?'':'s'} selected · ${count} unique tracks</span><button class="text-button" id="manage">Manage library ↗</button></div><div class="import-strip"><span>BRING YOUR OWN</span><button data-import="youtube">▷ YouTube</button><button data-import="csv">≋ Spotify CSV</button><button data-import="local">↥ Local files</button></div></section><section class="panel"><div class="panel-heading"><h2><span>☷</span> Make it your game</h2><span class="mini-label">SAVED AUTOMATICALLY</span></div><div class="settings-inner"><div class="label-row">Challenge mode</div><div class="segmented"><button id="intro" class="${settings.mode==='intro'?'selected':''}">↺ &nbsp; Intro Challenge</button><button id="random" class="${settings.mode==='random'?'selected':''}">⤨ &nbsp; Random Challenge</button></div><p class="mode-note">${settings.mode==='intro'?'Every song starts at 0:00. A classic for a reason.':'A random moment. The same starting point for every reveal.'}</p><div class="label-row"><span>Number of rounds</span><span class="round-control"><button id="minus" aria-label="Fewer rounds">−</button><input id="rounds" type="number" min="1" max="100" value="${settings.rounds}" aria-label="Number of rounds"><button id="plus" aria-label="More rounds">+</button></span></div><div class="divider"></div><div class="label-row"><span>Listen less. Earn more.</span><span class="mini-label">TOTAL SNIPPET LENGTH</span></div>${levels()}<button class="advanced" id="advanced">Customize snippets & points &nbsp; ↗</button></div></section></div><div class="start-row"><button class="start" id="start" ${!count?'disabled':''}>Let's play <span>→</span></button><p><strong>${Math.min(settings.rounds,count)} rounds · No repeats · Just good music</strong><br>${lists.some(l=>l.selected&&l.source==='demo')?'Demo includes original synth melodies. Learn them in My library.':'Your next “wait, I know this!” moment is one click away.'}</p></div><div class="precision-note">◉ &nbsp; Sample-accurate scheduling for local audio. YouTube timing is approximate. <button class="text-button" id="timing">Learn why ↗</button></div>`;
main.querySelectorAll('[data-list]').forEach(e=>e.onchange=()=>{lists.find(l=>l.id===e.dataset.list).selected=e.checked;save();render();});$('#add').onclick=()=>importModal();$('#manage').onclick=()=>navigate('library');bindImports();['intro','random'].forEach(mode=>$('#'+mode).onclick=()=>{settings.mode=mode;save();render();});$('#rounds').onchange=e=>{settings.rounds=Math.max(1,Math.min(100,Number(e.target.value)||1));save();render();};['minus','plus'].forEach(id=>$('#'+id).onclick=()=>{settings.rounds=Math.max(1,Math.min(100,settings.rounds+(id==='plus'?1:-1)));save();render();});$('#advanced').onclick=advanced;$('#timing').onclick=timing;$('#start').onclick=startGame;}
function modal(html){$('#modal-body').innerHTML='<button class="close" aria-label="Close dialog">×</button>'+html;$('#modal .close').onclick=()=>$('#modal').close();$('#modal').showModal();}$('#modal').addEventListener('close',()=>{if(!session)stop();});
function timing(){modal(`<h2>A note on the tiny snippets.</h2><p>Local audio is fully decoded before a round begins. An AudioBufferSourceNode schedules start and stop on the audio clock, at sample precision, with a short scheduling lead. Buffering and JavaScript timer delays don't determine its length. Hardware latency can delay when you hear it, but not the scheduled duration.</p><p>Keep this tab visible. Switching away cancels playback. Some audio files include silence at the beginning; Random Challenge may help.</p><div class="notice">YouTube cannot reliably deliver 0.1-second snippets. Its player uses asynchronous commands, keyframe seeks and buffered state updates. All YouTube intervals are approximate, and may overrun. The visible player, title, video and ads can reveal the answer. Nothing is hidden or extracted.</div>`);}
function advanced(){modal(`<h2>Your rules. Your points.</h2><p>Lengths are total audio, always replayed from the same starting point. Use increasing lengths and decreasing points.</p><form id="custom">${settings.lengths.map((l,i)=>`<div class="edit-grid"><label class="form-field">Stage ${i+1} · seconds<input name="s${i}" type="number" min="0.05" max="30" step="0.05" value="${l}" required></label><label class="form-field">Points<input name="p${i}" type="number" min="0" max="10000" step="1" value="${settings.points[i]}" required></label></div>`).join('')}<p id="custom-error" role="alert"></p><button class="primary">Save rules</button> <button type="button" id="reset-rules" class="secondary">Reset defaults</button></form>`);$('#reset-rules').onclick=()=>{settings.lengths=[...DEFAULTS.lengths];settings.points=[...DEFAULTS.points];save();$('#modal').close();render();};$('#custom').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),lengths=settings.lengths.map((_,i)=>Number(f.get('s'+i))),points=settings.points.map((_,i)=>Number(f.get('p'+i)));if(lengths.some((x,i)=>i&&x<=lengths[i-1])||points.some((x,i)=>i&&x>points[i-1])){$('#custom-error').textContent='Lengths must increase and points must stay the same or decrease.';return;}settings.lengths=lengths;settings.points=points;save();$('#modal').close();render();};}
async function startGame(){stop();await context().resume();const tracks=shuffle(pool());session={queue:tracks,index:0,total:Math.min(settings.rounds,tracks.length),results:[],score:0,stage:0,revealed:false,ready:false,heard:false,done:false};renderGame();await prepareRound();}
async function prepareRound(){if(!session)return;session.ready=false;session.stage=0;session.revealed=false;session.heard=false;session.error='';session.start=null;buffer=null;const token=session,track=session.queue[session.index];if(!track||session.results.length>=session.total){session.done=true;renderGame();return;}renderGame();try{if(track.source==='youtube'){await loadYT(track);}else{buffer=track.source==='demo'?demoBuffer(track):await context().decodeAudioData(await(await fileStore('get',track.id))?.arrayBuffer()||new ArrayBuffer(0));if(buffer.duration<settings.lengths.at(-1))throw Error('This audio is shorter than the longest snippet.');session.start=roundStart(buffer.duration,settings.lengths.at(-1),settings.mode);}if(session!==token)return;session.ready=true;renderGame();}catch(e){if(session!==token)return;session.error='Could not load this track. It has been skipped without using a round.';session.index++;session.total=Math.min(session.total,session.results.length+session.queue.length-session.index);toast(session.error);await prepareRound();}}
async function playSnippet(){if(playing||!session?.ready||session.revealed)return;await context().resume();session.heard=true;playing=true;const token=++playToken,duration=settings.lengths[session.stage];$('#play-snippet').textContent='Ⅱ';$('#play-snippet').classList.add('playing');$('#play-snippet').disabled=true;$('#play-caption').textContent='Listen closely…';if(buffer){const node=context().createBufferSource();node.buffer=buffer;node.connect(context().destination);source=node;node.onended=()=>{if(token===playToken)playFinished();};const when=context().currentTime+.04;node.start(when,session.start,duration);node.stop(when+duration);}else{if(session.start===null){const d=player.getDuration();if(!d){playFinished();toast('Player is still loading. Try the visible player, then replay.');return;}session.start=roundStart(d,settings.lengths.at(-1),settings.mode);}player.pauseVideo();player.seekTo(session.start,true);ytTarget=session.start+duration;ytArmed=true;player.playVideo();playTimer=setTimeout(()=>{if(playing){stop();playFinished();toast('YouTube did not start in time. Use the visible player, then replay.');}},20000);}}
function playFinished(){clearTimeout(playTimer);clearInterval(ytTimer);playing=false;if($('#play-snippet')){$('#play-snippet').textContent='▶';$('#play-snippet').classList.remove('playing');$('#play-snippet').disabled=false;$('#play-caption').textContent='Replay it. No points lost.';}}
function finishRound(correct,unavailable=false){stop();session.revealed=true;session.last={...session.queue[session.index],earned:correct?settings.points[session.stage]:0,stage:session.stage,correct,unavailable};session.score+=session.last.earned;session.results.push(session.last);renderGame();}
function renderGame(){if(!session)return;const s=session;if(s.done){main.innerHTML=`<section class="game"><div class="eyebrow" style="justify-content:center">THAT'S A WRAP</div><h1>Your ears did you proud.</h1><p class="lead" style="margin:auto">${s.results.filter(r=>r.correct).length} of ${s.results.length} songs guessed. Ready for an encore?</p><div class="points">${s.score.toLocaleString()} <span>total points</span></div><div class="results-list">${s.results.map((r,i)=>`<div class="track-row"><span class="mini-label">${String(i+1).padStart(2,'0')}</span><div class="collection-info"><strong>${esc(r.title)}</strong><small>${esc(r.artist)} · ${r.correct?settings.lengths[r.stage]+' s':'Skipped'}</small></div><span>+${r.earned.toLocaleString()}</span></div>`).join('')}</div><button class="start" id="again" style="margin:auto">Play again <span>↺</span></button><button class="text-button" id="back" style="margin-top:20px">Back to setup</button></section>`;$('#again').onclick=startGame;$('#back').onclick=()=>{session=null;render();};return;}
const track=s.queue[s.index];const yt=track?.source==='youtube';if(!yt&&player){player.destroy();player=null;} // Preserve the real iframe across re-renders. Never hide or cover it.
let ytElement=$('#yt-container');if(ytElement)ytElement.remove();main.innerHTML=`<section class="game"><div class="game-top"><button class="text-button" id="exit">← End game</button><span>ROUND ${s.results.length+(s.revealed?0:1)} / ${s.total}</span><span>${s.score.toLocaleString()} pts</span></div><div class="session-progress"><div style="width:${s.results.length/s.total*100}%"></div></div><div class="panel">${s.revealed?`<div class="eyebrow" style="justify-content:center">${s.last.correct?'GOOD EARS. GREAT GUESS.':'ONE FOR THE NEXT PLAYLIST.'}</div><div class="result-icon">${s.last.correct?'✦':'♫'}</div><h2 class="answer-title">${esc(track.title)}</h2><p class="answer-artist">${esc(track.artist)}</p><div class="points">+${s.last.earned.toLocaleString()} <span>points</span></div><p class="mode-note">${s.last.correct?'You got it with '+settings.lengths[s.stage]+' seconds.':'No worries. The next one might be your song.'}</p><button class="primary" id="next">${s.results.length>=s.total?'See results':'Next song'} →</button>`:`<div class="eyebrow" style="justify-content:center">${settings.mode==='intro'?'INTRO CHALLENGE':'RANDOM CHALLENGE'}</div><h1>What's that song?</h1><div class="points">${settings.points[s.stage].toLocaleString()} <span>points up for grabs</span></div><div class="play-orbit"><button class="play-button" id="play-snippet" ${!s.ready?'disabled':''} aria-label="Play current snippet">▶</button></div><p class="play-caption" id="play-caption">${s.ready?'Play '+settings.lengths[s.stage]+' seconds. Trust your first instinct.':'Preparing your audio…'}</p>${levels(s.stage)}<form class="guess-form" id="guess-form"><input id="guess" aria-label="Song title" placeholder="You know this one… song title?" autocomplete="off" required ${!s.ready?'disabled':''}><button class="primary" ${!s.ready?'disabled':''}>Guess →</button></form><p class="feedback" id="feedback" role="status"></p><div class="game-actions"><button class="secondary" id="reveal" ${!s.ready||s.stage===settings.lengths.length-1?'disabled':''}>Hear more ${s.stage<3?'· '+settings.lengths[s.stage+1]+' s':''} →</button><button class="text-button" id="skip" ${!s.ready?'disabled':''}>Skip song ↗</button></div>`}<div id="yt-slot"></div></div><p class="precision-note">${yt?'◉ YouTube · approximate timing · visible player may reveal the answer':'◉ Local audio · audio-clock scheduling · free replays'}</p></section>`;
if(ytElement&&yt)$('#yt-slot').append(ytElement);else if(yt)$('#yt-slot').innerHTML='<div class="yt-area" id="yt-container"><div id="youtube-player"></div><p>YouTube stays visible, including video, title, controls and ads. Timing is approximate, especially at 0.1 s. Do not use the player controls for a competitive score. If unavailable or an ad plays, use “Replace track”.</p><button class="text-button" id="replace-track">Replace track (no round lost) ↗</button></div>';
if($('#replace-track'))$('#replace-track').onclick=()=>{stop();s.index++;s.total=Math.min(s.total,s.results.length+s.queue.length-s.index);prepareRound();};$('#exit').onclick=()=>navigate('play');if(s.revealed){$('#next').onclick=()=>{stop();s.index++;prepareRound();};return;}$('#play-snippet').onclick=playSnippet;$('#reveal').onclick=()=>{stop();s.stage++;s.heard=false;renderGame();};$('#skip').onclick=()=>finishRound(false);$('#guess-form').onsubmit=e=>{e.preventDefault();if(!s.heard){$('#feedback').textContent='Play your snippet first, then make your guess.';return;}if(matches($('#guess').value,track.title,track.artist))finishRound(true);else{$('#feedback').textContent='Not quite. Try another guess, replay, or hear a little more.';$('#guess').select();}};}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){stop();if(session&&!session.revealed)playFinished();}});
// Official visible YouTube iframe only. No stream URLs, extraction or hidden playback.
let ytTarget=0,ytArmed=false;async function loadYT(track){if(!ytReady)ytReady=new Promise((resolve,reject)=>{if(window.YT?.Player)return resolve();const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.onerror=()=>reject(Error('YouTube could not be reached'));window.onYouTubeIframeAPIReady=resolve;document.head.append(script);setTimeout(()=>reject(Error('YouTube API timed out')),15000);});await ytReady;return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Player timed out')),15000);if(player){player.destroy();player=null;const area=$('#yt-container');area.querySelector('iframe')?.remove();area.querySelector('#youtube-player')?.remove();const div=document.createElement('div');div.id='youtube-player';area.prepend(div);}player=new YT.Player('youtube-player',{width:480,height:270,videoId:track.videoId,playerVars:{playsinline:1,origin:location.origin},events:{onReady:()=>{clearTimeout(timeout);resolve();},onError:()=>{clearTimeout(timeout);if(session?.ready&&!session.revealed){stop();session.index++;session.total=Math.min(session.total,session.results.length+session.queue.length-session.index);toast('Unavailable YouTube track replaced.');prepareRound();}else reject(Error('Unavailable video'));},onStateChange:e=>{if(e.data===1&&ytArmed&&playing){ytArmed=false;clearInterval(ytTimer);ytTimer=setInterval(()=>{if(player.getCurrentTime()>=ytTarget){player.pauseVideo();playFinished();}},10);}if(e.data===0&&playing)playFinished();}}});});}
function bindImports(){main.querySelectorAll('[data-import]').forEach(b=>b.onclick=()=>importModal(b.dataset.import));}
function importModal(type='local'){modal(`<h2>Bring your own soundtrack.</h2><p>Your collection stays in this browser. No uploads, no account needed.</p><div class="segmented" style="margin:20px 0">${[['local','Local audio'],['youtube','YouTube'],['csv','Spotify CSV']].map(([v,l])=>`<button data-tab="${v}" class="${type===v?'selected':''}">${l}</button>`).join('')}</div><form id="import-form"><label class="form-field">Collection name<input id="collection-name" required maxlength="80" placeholder="e.g. The late-night rotation"></label>${type==='local'?`<label class="form-field">Audio files<input id="files" type="file" accept="audio/*,.mp3,.wav,.m4a,.ogg,.flac" multiple required></label><p>MP3, WAV, AAC and other formats your browser can decode. Use “Artist - Title” filenames for automatic labels. You can edit everything later. Files are saved on this device using IndexedDB.</p>`:type==='csv'?`<label class="form-field">Playlist CSV<input id="files" type="file" accept=".csv,text/csv" required></label><p>Accepts Track Name / Title and Artist Name(s) / Artist columns. CSVs contain metadata, not playable music. In My library, attach audio you own to each track. No Spotify account or API is used.</p>`:`<label class="form-field">Public playlist URL or ID<input id="playlist-url" required placeholder="https://www.youtube.com/playlist?list=…"></label><label class="form-field">YouTube Data API v3 key<input id="api-key" type="password" required autocomplete="off" placeholder="Paste a restricted browser API key"></label><p>Enable YouTube Data API v3 in Google Cloud Console. Create a key restricted to this website's HTTP referrer and this API. The key is used for this import only and is not saved. Public playlists only. Playback doesn't need a key.</p><div class="notice">YouTube must stay visible. Its title and video can reveal answers. All snippet durations are approximate; 0.1 s cannot be guaranteed. Ads are not bypassed.</div>`}<p id="import-error" role="alert"></p><button class="primary" id="import-submit">Import ${type==='local'?'audio':type==='csv'?'metadata':'playlist'} →</button></form>`);$('#modal').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{$('#modal').close();importModal(b.dataset.tab);});$('#import-form').onsubmit=async e=>{e.preventDefault();const btn=$('#import-submit');btn.disabled=true;btn.textContent='Importing…';try{const name=$('#collection-name').value.trim();let tracks=[];if(type==='local'){for(const file of $('#files').files){const id=uid(),parts=file.name.replace(/\.[^.]+$/,'').split(' - ');await fileStore('put',id,file);tracks.push({id,title:parts.length>1?parts.slice(1).join(' - '):parts[0],artist:parts.length>1?parts[0]:'Unknown artist',source:'local'});}}else if(type==='csv'){tracks=csvTracks(await $('#files').files[0].text()).map(t=>({...t,id:uid()}));}else{tracks=await importYouTube($('#playlist-url').value.trim(),$('#api-key').value.trim());}if(!tracks.length)throw Error('No available tracks found in this collection.');lists.push({id:uid(),name,source:type==='local'?'local':type==='csv'?'metadata':'youtube',selected:true,tracks,importedAt:new Date().toISOString()});save();$('#modal').close();render();toast(tracks.length+' tracks added to your library.');}catch(err){$('#import-error').textContent=err.message;btn.disabled=false;btn.textContent='Try import again';}};}
async function importYouTube(value,key){let id=value;try{id=new URL(value).searchParams.get('list')||'';}catch{}if(!/^[A-Za-z0-9_-]{10,}$/.test(id))throw Error('Enter a valid public YouTube playlist URL or ID.');let tracks=[],pageToken='';do{const url=new URL('https://www.googleapis.com/youtube/v3/playlistItems');url.search=new URLSearchParams({part:'snippet,contentDetails',maxResults:'50',playlistId:id,key,...(pageToken?{pageToken}:{})});const r=await fetch(url);const data=await r.json();if(!r.ok)throw Error(data.error?.message||'Playlist import failed. Check the key and playlist visibility.');for(const i of data.items||[]){const s=i.snippet;if(['Deleted video','Private video'].includes(s.title))continue;let title=s.title.replace(/\s*[\[(](official.*?|.*?lyrics.*?|.*?music video.*?)[\])]/gi,'').trim(),artist=s.videoOwnerChannelTitle||s.channelTitle||'Unknown artist';if(title.includes(' - ')){[artist,...title]=title.split(' - ');title=title.join(' - ');}tracks.push({id:uid(),title,artist:artist.replace(/ - Topic$/,''),videoId:i.contentDetails.videoId,source:'youtube'});}pageToken=data.nextPageToken||'';if(tracks.length>=2000&&pageToken)throw Error('This playlist exceeds 2,000 tracks. Import a smaller playlist.');}while(pageToken);return uniqueTracks(tracks);}
function renderLibrary(){main.innerHTML=`<div class="eyebrow">YOUR PERSONAL ROTATION</div><h1 class="page-title">Good music lives here.</h1><p class="lead">Bring a playlist. Fix a title. Make it yours.</p><div class="library-actions"><button class="primary" data-import="local">＋ Local audio</button><button class="secondary" data-import="youtube">▷ YouTube playlist</button><button class="secondary" data-import="csv">≋ Spotify CSV</button></div>${lists.map(l=>`<section class="panel library-block"><div class="label-row"><h2>${esc(l.name)}</h2><button class="text-button" data-remove="${l.id}">Remove collection</button></div><p class="mode-note">${l.tracks.length} tracks · ${l.source==='demo'?'Original synth melodies. Preview to learn the demo songs.':l.source==='metadata'?'Attach local audio to make CSV tracks playable.':'Saved on this browser. Edit titles for more accurate guesses.'}</p>${l.tracks.map(t=>`<div class="track-row"><span class="cover" style="width:34px;height:34px;font-size:16px">♫</span><span class="collection-info"><strong>${esc(t.title)}</strong><small>${esc(t.artist)} <span class="badge">${t.source==='metadata'?'· Needs audio':''}</span></small></span>${t.source==='demo'||t.source==='local'?`<button class="secondary" data-preview="${t.id}" aria-label="Preview ${esc(t.title)}">▷</button>`:''}<button class="text-button" data-edit="${t.id}">Edit</button>${t.source==='metadata'?`<button class="secondary" data-attach="${t.id}">Attach audio</button>`:''}</div>`).join('')}</section>`).join('')}`;bindImports();main.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{modal('<h2>Remove this collection?</h2><p>Its metadata and local audio will be removed from this browser.</p><button class="primary" id="confirm-remove">Remove collection</button>');$('#confirm-remove').onclick=async()=>{const l=lists.find(l=>l.id===b.dataset.remove);try{for(const t of l.tracks)if(t.source==='local')await fileStore('delete',t.id);lists=lists.filter(x=>x!==l);save();$('#modal').close();render();}catch(e){toast(e.message);}};});main.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editTrack(b.dataset.edit));main.querySelectorAll('[data-attach]').forEach(b=>b.onclick=()=>attachTrack(b.dataset.attach));main.querySelectorAll('[data-preview]').forEach(b=>b.onclick=async()=>{try{stop();const t=findTrack(b.dataset.preview);await context().resume();const buf=t.source==='demo'?demoBuffer(t):await context().decodeAudioData(await(await fileStore('get',t.id)).arrayBuffer());source=context().createBufferSource();source.buffer=buf;source.connect(context().destination);source.start(context().currentTime+.04,0,Math.min(4,buf.duration));toast('Playing a 4-second preview of '+t.title);}catch(e){toast('This audio could not be decoded. Try a supported format.');}});}
function findTrack(id){return lists.flatMap(l=>l.tracks).find(t=>t.id===id);}function editTrack(id){const t=findTrack(id);modal(`<h2>A little metadata tune-up.</h2><form id="edit-form"><label class="form-field">Song title<input id="edit-title" required value="${esc(t.title)}"></label><label class="form-field">Artist<input id="edit-artist" required value="${esc(t.artist)}"></label><button class="primary">Save changes</button></form>`);$('#edit-form').onsubmit=e=>{e.preventDefault();const title=$('#edit-title').value.trim(),artist=$('#edit-artist').value.trim();if(!title||!artist)return;t.title=title;t.artist=artist;save();$('#modal').close();render();};}
function attachTrack(id){modal('<h2>Give this song its sound.</h2><p>Attach a local copy you own. This file will be saved only on this device.</p><form id="attach-form"><label class="form-field">Audio file<input id="attach-file" type="file" accept="audio/*" required></label><p id="attach-error" role="alert"></p><button class="primary">Attach audio</button></form>');$('#attach-form').onsubmit=async e=>{e.preventDefault();try{const file=$('#attach-file').files[0];await context().decodeAudioData(await file.arrayBuffer());await fileStore('put',id,file);findTrack(id).source='local';save();$('#modal').close();render();}catch{$('#attach-error').textContent='Could not decode or store this file. Try MP3 or WAV with browser storage enabled.';}};}
function renderHelp(){main.innerHTML=`<article class="help"><div class="eyebrow">A LITTLE AUDIO. A BIG GUESS.</div><h1 class="page-title">Meet your next music obsession.</h1><h2>01 / Pick your soundtrack</h2><p>Select one or more collections. Start with the original synth demo, import local audio, or add a public YouTube playlist with your own API key. Spotify CSV imports contain metadata: attach local audio in My library before playing.</p><h2>02 / Listen, guess, repeat</h2><p>Start with 0.1 seconds for 1,000 points. Need more? Reveal 0.5 seconds for 900 points, 1 second for 800, or 3 seconds for 500. Each snippet is the total duration, always from the same starting position. Replays and incorrect guesses are free. Use Hear more only when you want to lower the available score. Skip reveals the answer and scores zero.</p><h2>03 / Pick your challenge</h2><p>Intro Challenge starts every track at 0:00. Random Challenge chooses a random point, kept constant for the whole round. Songs do not repeat within a game, even across selected playlists. If there are fewer playable tracks than requested rounds, your game is shortened. Unavailable tracks are replaced where possible.</p><h2>Tiny snippets deserve honest timing.</h2><p>Decoded local files use the Web Audio clock for sample-accurate snippet duration. Startup is scheduled slightly ahead; output-device latency can delay sound. YouTube commands are asynchronous and seeks can land on keyframes. YouTube snippets are approximate, particularly at 0.1 seconds, and its visible video, title and ads may reveal answers. We never hide the player, extract streaming audio or bypass ads.</p><button class="secondary" id="timing">More about audio precision ↗</button><h2>Your library is yours.</h2><p>Settings and playlist metadata live in localStorage; local audio lives in IndexedDB on this browser. Clearing site data removes them. Audio files never leave your device. YouTube imports send your API key directly to Google for that import; GuessKar does not save the key. No accounts, lobbies or multiplayer.</p><h2>YouTube API key setup</h2><p>In <a href="https://console.cloud.google.com/apis/library/youtube.googleapis.com" target="_blank" rel="noopener">Google Cloud Console ↗</a>, enable YouTube Data API v3. Create an API key, restrict its API access to YouTube Data API v3 and its website referrers to your deployed domain (and localhost for development). Paste it into the import dialog. API quota and public playlist visibility apply.</p><button class="primary" id="go-play" style="margin-top:20px">Let's play →</button></article>`;$('#timing').onclick=timing;$('#go-play').onclick=()=>navigate('play');}
render();
